/**
 * How Arabesque flower with a floating figured border in a circle (`maru-ni-karahana-fusen-ryo`) is constructed, in a line in each language: the text a crest's card shows beside its steps.
 * It is here, not on the crest's record, so that the manifest stays small; `crestConstruction()` loads it.
 *
 * @example
 * ```ts no-run
 * import { description } from "@johnmorrisdotca/kamon-crests/steps/maru-ni-karahana-fusen-ryo";
 *
 * console.log(description.en.length > 30, description.ja.endsWith("。")); // true true
 * ```
 */
const description: { en: string; ja: string } = {"en":"A small five-petalled arabesque flower stands in the middle of a ring, its first petal upright. A short forked vine with two rolled ends grows from the tip of each petal. Five half flowers stand on the inside of the ring between the vines and open towards the middle. Each has one scalloped petal pointing inwards and two long side petals that run along the ring until they almost meet the next flower.","ja":"輪の中央に、五枚の花びらの小さな唐花を、一枚目を真上に向けて置きます。各花びらの先から、先が二つに分かれて巻く短い蔓を伸ばします。蔓と蔓の間には、輪の内側に半分の花を五つ置き、中央に向けて開きます。半分の花は、内へ向く丸いふくらみのある花びら一枚と、輪に沿って隣の花の近くまで伸びる長い花びら二枚でできています。"};

export default construction;
export { construction, description };
